dst.execute(text(f"TRUNCATE TABLE {table_name} CASCADE"))

# Detect self-referential FK columns (e.g. topics.parent_id → topics.id).
# These require a two-pass insert: first NULL, then UPDATE, so Postgres
# doesn't reject rows whose parent hasn't been inserted yet.
self_ref_cols = []
if table_name in Base.metadata.tables:
    tbl = Base.metadata.tables[table_name]
    for col in tbl.columns:
        for fk in col.foreign_keys:
            if fk.column.table.name == table_name:
                self_ref_cols.append(col.name)

if self_ref_cols:
    # Pass 1: insert with self-ref cols nulled out
    nulled = [{**row, **{c: None for c in self_ref_cols}} for row in converted]
    dst.execute(Base.metadata.tables[table_name].insert(), nulled)
    # Pass 2: restore actual self-ref values
    for row in converted:
        updates = {c: row[c] for c in self_ref_cols if row.get(c) is not None}
        if updates:
            set_clause = ", ".join(f"{c} = :{c}" for c in updates)
            dst.execute(
                text(f"UPDATE {table_name} SET {set_clause} WHERE id = :id"),
                {**updates, "id": row["id"]},
            )
elif table_name in Base.metadata.tables:
    dst.execute(Base.metadata.tables[table_name].insert(), converted)
else:
    # Fallback: use column names from first row
    cols = ", ".join(converted[0].keys())
    placeholders = ", ".join(f":{k}" for k in converted[0].keys())
    dst.execute(
        text(f"INSERT INTO {table_name} ({cols}) VALUES ({placeholders})"),
        converted,
    )
dst.commit()

